var n=`0152-dovga`;var t=`world-0152`;var s=`AZ`;var a=`western-asia`;var r=4;var g=40;var o={en:`Dovga`,ua:`Довга`};var l={en:`A classic dish from Azerbaijan, featuring white rice, plain yogurt, chicken egg, canned chickpeas. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Азербайджан. Основні складники: білий рис, натуральний йогурт, куряче яйце, консервований нут. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 15 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 15 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:15,i:[[`white-rice`,90,`g`],[`water`,420,`ml`]]},{en:`Whisk or whip the listed ingredients to a smooth, light consistency, then keep cool until needed.`,ua:`Збийте зазначені складники до гладкої легкої консистенції, після чого зберігайте в прохолоді до використання.`,t:[`whipping`],m:7,i:[[`plain-yogurt`,1e3,`g`],[`chicken-egg`,1,`pcs`],[`all-purpose-flour`,30,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 15 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 15 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:15,i:[[`canned-chickpeas`,240,`g`],[`spinach`,220,`g`],[`dill`,40,`g`],[`parsley`,30,`g`],[`cilantro`,25,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`mint`,15,`g`],[`table-salt`,null,`to_taste`]]}];var h={slug:n,id:t,country:`AZ`,region:a,servings:4,minutes:40,title:o,text:l,steps:d};export{s as country,h as default,t as id,g as minutes,a as region,r as servings,n as slug,d as steps,l as text,o as title};